export interface Env { DB: D1Database; }
export default { async fetch(request: Request, env: Env): Promise<Response> { const url = new URL(request.url); if (url.pathname === "/health") return Response.json({ service: "omnia-auth", status: "ok", environment: "staging" }); if (url.pathname === "/auth/request-confirmation" && request.method === "POST") { const body = await request.json<{email?: string}>(); if (!body.email || !body.email.includes("@")) return Response.json({error:"E-mail inválido."},{status:400}); return Response.json({message:"Solicitação recebida; SMTP ainda não configurado."},{status:202}); } return Response.json({service:"omnia-auth",status:"not_found"},{status:404}); } };
